472|		XMLElement* sub[3] = { doc->NewElement( "sub" ), doc->NewElement( "sub" ), doc->NewElement( "sub" ) };
473|		for( int i=0; i<3; ++i ) {
474|			sub[i]->SetAttribute( "attrib", i );
475|		}
