522|			XMLTest( "Compact mode", "<element><sub attrib=\"true\"/><sub/></element>", streamer.CStr(), false );
523|		}
524|		doc->SaveFile( "./resources/out/pretty.xml" );
525|		XMLTest( "Save pretty.xml", false, doc->Error() );
